// src/services/api.js
export async function fetchSchools() {
  const response = await fetch("http://127.0.0.1:8000/api/schools/");
  return await response.json();
}

export async function fetchSchoolById(id) {
  const response = await fetch(`http://127.0.0.1:8000/api/schools/${id}/`);
  if (!response.ok) {
    throw new Error(`Failed to fetch school: ${response.statusText}`);
  }
  return await response.json();
}
